from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        rows = [r for r in packages[name]
                if r["version"] not in blocked.get(name, [])
                and (name not in pins or pins[name] == r["version"])]
        choices.append([None] + rows)

    best_vector = None
    best_versions = None
    for selection in product(*choices):
        assigned = {name: row for name, row in zip(names, selection)
                    if row is not None}
        if any(root not in assigned or not
               (bounds[0] <= assigned[root]["version"] <= bounds[1])
               for root, bounds in data["roots"].items()):
            continue
        edges = {}
        valid = True
        for name, row in assigned.items():
            deps = [d for d in row.get("deps", [])
                    if not d.get("feature") or d["feature"] in features]
            edges[name] = []
            for dep in deps:
                target = assigned.get(dep["name"])
                if target is None or not dep["min"] <= target["version"] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue
        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(assigned):
            continue
        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in assigned):
            continue
        vector_names = sorted(names, reverse=(order == "descending"))
        vector = tuple(assigned[n]["version"] if n in assigned else -1
                       for n in vector_names)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector = vector
            best_versions = {n: row["version"] for n, row in assigned.items()}
    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _dep(order, maximize):
    return lambda data: dependency_solver(data, order, maximize)


def _rounded(n, d, mode):
    return (n + d // 2) // d if mode == "half_up" else n // d


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if eid not in winners or key > winners[eid][0]:
            winners[eid] = (key, event)
    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = _rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def quota_jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    available = [j for j in jobs if j["id"] not in blocked]
    for chosen in combinations(available, k):
        ids = sorted(j["id"] for j in chosen)
        idset = set(ids)
        if not mandatory <= idset:
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda j: (j["start"], j["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(j["value"] for j in chosen)
        if best_value is None or value > best_value or (value == best_value and ids > best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal(data):
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = 0
    if data["source"] in indexes:
        initial_mask |= 1 << indexes[data["source"]]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start_state = (data["source"], data["coupons"], initial_mask)
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and remaining == 0 and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for used in (0, 1) if remaining else (0,):
                duration = edge["duration"]
                if used:
                    duration = max(1, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask
                if next_node in indexes:
                    next_mask |= 1 << indexes[next_node]
                next_state = (next_node, remaining - used, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


SOLVERS = {
    "component_01": _dep("descending", False),
    "component_02": _dep("ascending", True),
    "component_03": _dep("ascending", False),
    "component_04": _dep("descending", True),
    "component_05": _dep("descending", False),
    "component_06": ledger,
    "component_07": quota_jobs,
    "component_08": temporal,
}
